#!/usr/bin/env python3
"""Generate procedural zone maps for TextQuest."""

import os
import sys
from pathlib import Path

def create_zone_map(bounds, rooms, pois):
    """Generate a map file for a zone."""
    lines = []
    
    x_min, x_max, y_min, y_max = bounds
    lines.append(f"L {x_min}, {y_min}, 0.0, {x_max}, {y_min}, 0.0, 0, 0, 0")
    lines.append(f"L {x_max}, {y_min}, 0.0, {x_max}, {y_max}, 0.0, 0, 0, 0")
    lines.append(f"L {x_max}, {y_max}, 0.0, {x_min}, {y_max}, 0.0, 0, 0, 0")
    lines.append(f"L {x_min}, {y_max}, 0.0, {x_min}, {y_min}, 0.0, 0, 0, 0")
    
    for room in rooms:
        x1, y1, x2, y2, z = room
        lines.append(f"L {x1}, {y1}, {z}, {x2}, {y1}, {z}, 150, 120, 80")
        lines.append(f"L {x2}, {y1}, {z}, {x2}, {y2}, {z}, 150, 120, 80")
        lines.append(f"L {x2}, {y2}, {z}, {x1}, {y2}, {z}, 150, 120, 80")
        lines.append(f"L {x1}, {y2}, {z}, {x1}, {y1}, {z}, 150, 120, 80")
    
    for poi in pois:
        x, y, z, r, g, b, size, label = poi
        lines.append(f"P {x}, {y}, {z}, {r}, {g}, {b}, {size}, {label}")
    
    return "\n".join(lines)

