def main():
    """Generate all procedural zone maps."""
    map_dir = Path("config/maps")
    map_dir.mkdir(parents=True, exist_ok=True)
    
    generated = 0
    for zone_name, (bounds, rooms, pois) in ZONES.items():
        content = create_zone_map(bounds, rooms, pois)
        filepath = map_dir / f"{zone_name}.txt"
        with open(filepath, "w") as f:
            f.write(content)
        generated += 1
        print(f"Generated {zone_name}")
    
    print(f"\nSuccessfully generated {generated} zone maps")
    return 0

if __name__ == "__main__":
    sys.exit(main())
